<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { ArrowLeft, Clock3, MessageCircle, RefreshCw, Send, ShieldCheck, Sparkles, UserRound } from 'lucide-vue-next';
import AppHeader from './AppHeader.vue';

const props = defineProps({ user: { type: Object, default: null } });
const emit = defineEmits(['back', 'account']);
const session = ref(null);
const result = ref(null);
const reply = ref('');
const suggestions = ref([]);
const busy = ref(false);
const notice = ref('');
const now = ref(Date.now());
let timer = null;

const remainingMs = computed(() => session.value ? Math.max(0, session.value.expiresAt - now.value) : 180000);
const remainingSeconds = computed(() => Math.ceil(remainingMs.value / 1000));
const remainingLabel = computed(() => `${Math.floor(remainingSeconds.value / 60)}:${String(remainingSeconds.value % 60).padStart(2, '0')}`);
const progress = computed(() => session.value ? Math.max(0, Math.min(100, remainingMs.value / 180000 * 100)) : 100);
const messages = computed(() => session.value?.history || []);
const canReply = computed(() => Boolean(session.value && session.value.status === 'active' && remainingMs.value > 0 && !busy.value));

async function requestJSON(url, options = {}) {
  const response = await fetch(url, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.message || '请求失败');
  return body;
}

function resetView() {
  session.value = null;
  result.value = null;
  reply.value = '';
  suggestions.value = [];
  notice.value = '';
}

async function start() {
  if (busy.value) return;
  if (!props.user) { emit('account'); return; }
  busy.value = true; notice.value = '';
  try {
    const data = await requestJSON('/api/customer-service/start', { method: 'POST', body: '{}' });
    session.value = data.session;
    suggestions.value = data.session.scenario.suggestedReplies || [];
    now.value = Date.now();
  } catch (error) { notice.value = error.message; }
  finally { busy.value = false; }
}

function useSuggestion(text) {
  reply.value = text;
}

async function sendReply() {
  if (!canReply.value || !reply.value.trim()) return;
  const text = reply.value.trim();
  const pendingMessage = { role: 'agent', content: text, timestamp: Date.now(), pending: true };
  reply.value = '';
  // 先把客服气泡写入本地会话，网络请求和模型响应不会阻塞用户看到自己的消息。
  session.value.history = [...(session.value.history || []), pendingMessage];
  busy.value = true; notice.value = '';
  try {
    const data = await requestJSON('/api/customer-service/reply', { method: 'POST', body: JSON.stringify({ sessionId: session.value.id, reply: text }) });
    session.value.history = data.history;
    suggestions.value = data.turn.suggestedReplies || [];
    now.value = Date.now();
  } catch (error) {
    session.value.history = (session.value.history || []).filter((item) => item !== pendingMessage);
    reply.value = text;
    notice.value = error.message;
  } finally { busy.value = false; }
}

async function finish() {
  if (!session.value || result.value || busy.value) return;
  busy.value = true; notice.value = '';
  try {
    const data = await requestJSON('/api/customer-service/finish', { method: 'POST', body: JSON.stringify({ sessionId: session.value.id }) });
    result.value = data.result;
    session.value.status = 'finished';
  } catch (error) { notice.value = error.message; }
  finally { busy.value = false; }
}

function formatLatency(value) {
  if (value === null || value === undefined) return '暂无';
  return `${Math.max(0, Math.round(value / 1000))} 秒`;
}

onMounted(() => {
  timer = window.setInterval(() => {
    now.value = Date.now();
    if (session.value && !result.value && remainingMs.value <= 0 && !busy.value) finish();
  }, 250);
});
onBeforeUnmount(() => window.clearInterval(timer));
</script>

<template>
  <section class="customer-service-game">
    <AppHeader title="电商客服挑战" subtitle="CUSTOMER SERVICE LAB" :icon="MessageCircle" back-label="游戏大厅" :user="props.user" @back="emit('back')" @account="emit('account')" />
    <main class="customer-service-shell">
      <div class="customer-service-shopbar"><div class="customer-service-shopbrand"><span class="customer-service-shoplogo">铺</span><div><strong>练习优选旗舰店</strong><small>官方客服工作台</small></div></div><div class="customer-service-shoplinks"><span>店铺首页</span><span>商品管理</span><span class="is-active">售后服务</span><span>服务规则</span></div><div class="customer-service-shopstate"><span class="customer-service-online-dot"></span>客服在线</div></div>
      <div class="customer-service-breadcrumb"><button type="button" @click="emit('back')"><ArrowLeft :size="15"/>返回游戏大厅</button><span>›</span><strong>电商客服挑战</strong></div>
      <section v-if="!session" class="customer-service-intro">
        <div class="customer-service-intro-copy"><p class="customer-service-kicker"><Sparkles :size="16"/>AI 情景训练</p><h1>三分钟，练出更稳的客服回复。</h1><p>你扮演电商客服，消费者由 AI 扮演。每一轮会给出建议话术，你需要在倒计时内回复；结束后系统会按照回复速度、礼貌共情、问题理解和方案有效性进行评分。</p><div class="customer-service-rules"><span><Clock3 :size="17"/>限时 3 分钟</span><span><ShieldCheck :size="17"/>服务端保护密钥</span><span><MessageCircle :size="17"/>固定 JSON 交互</span></div><button class="customer-service-primary" type="button" :disabled="busy" @click="start"><Sparkles :size="17"/>{{ busy ? '正在准备场景…' : '开始客服挑战' }}</button><p v-if="notice" class="customer-service-notice" role="alert">{{ notice }}</p></div>
        <aside class="customer-service-preview"><div class="customer-service-preview-icon"><UserRound :size="26"/></div><strong>你是客服</strong><p>先确认诉求，再说明处理路径。建议话术只做参考，最终回复由你决定。</p><div class="customer-service-preview-chat"><span>消费者</span><p>“物流两天没更新，今晚就要送人了，怎么办？”</p></div></aside>
      </section>
      <section v-else-if="!result" class="customer-service-running">
        <header class="customer-service-running-header"><div><p class="customer-service-kicker"><span class="customer-service-store-tag">售后接待</span>{{ session.scenario.title }}</p><h1>接待这位消费者</h1><p>{{ session.scenario.context }}</p></div><div class="customer-service-clock" :class="{ 'is-warning': remainingSeconds <= 30 }"><span>本轮服务倒计时</span><strong>{{ remainingLabel }}</strong><small>及时回复会获得更高速度分</small></div></header>
        <div class="customer-service-order-strip"><div class="customer-service-product-thumb">优选</div><div class="customer-service-order-main"><span>订单号 B20261028</span><strong>基础款日常服饰</strong><small>商品未使用 · 保留吊牌和包装</small></div><div class="customer-service-order-meta"><span>订单状态</span><b>待客服处理</b></div><div class="customer-service-order-meta"><span>客户诉求</span><b>换货咨询</b></div></div>
        <div class="customer-service-progress"><i :style="{ width: `${progress}%` }"></i></div>
        <div class="customer-service-grid"><section class="customer-service-card customer-service-profile"><header><span class="customer-service-avatar"><UserRound :size="17"/></span><div><strong>消费者画像</strong><small>平台会员 · 已实名</small></div></header><p>{{ session.scenario.profile }}</p><div><span>核心场景</span><b>{{ session.scenario.title }}</b></div><div class="customer-service-profile-tags"><span>首次购买</span><span>希望尽快处理</span></div></section><section class="customer-service-card customer-service-conversation"><header><span class="customer-service-section-icon"><MessageCircle :size="17"/></span><div><strong>消费者会话</strong><small><i class="customer-service-online-dot"></i>{{ busy ? 'AI 正在回复…' : '消费者在线' }}</small></div><span>{{ messages.filter(item => item.role === 'agent').length }} 次回复</span></header><div class="customer-service-messages" aria-live="polite"><article v-for="(item, index) in messages" :key="`${item.timestamp}-${index}`" :class="[item.role, { 'is-pending': item.pending }]" aria-live="polite"><span>{{ item.role === 'customer' ? '消费者 · 刚刚' : '你 · 客服' }}<small v-if="item.pending"> · 已发送，等待 AI 回复</small><small v-else-if="item.mood"> · {{ item.mood }}</small></span><p>{{ item.content }}</p></article></div><div class="customer-service-composer"><textarea v-model="reply" rows="3" :disabled="!canReply" placeholder="请像真实客服一样回复消费者…" @keydown.ctrl.enter.prevent="sendReply"></textarea><button class="customer-service-primary" type="button" :disabled="!canReply || !reply.trim()" @click="sendReply"><Send :size="16"/>{{ busy ? 'AI 回复中…' : '发送回复' }}</button><small>Ctrl / ⌘ + Enter 发送 · 回复越快，速度评分越高</small></div></section><aside class="customer-service-card customer-service-suggestions"><header><span class="customer-service-section-icon"><Sparkles :size="17"/></span><div><strong>客服工作台</strong><small>AI 辅助建议</small></div></header><div class="customer-service-service-state"><span class="customer-service-online-dot"></span>服务进行中</div><p>建议话术可直接使用，也可以按你的判断改写。</p><button v-for="item in suggestions" :key="item" type="button" @click="useSuggestion(item)">{{ item }}</button><div class="customer-service-quick-links"><span>常用服务</span><a href="#" @click.prevent="useSuggestion('您好，我先为您核实订单信息，请稍等。')">核实订单</a><a href="#" @click.prevent="useSuggestion('很抱歉给您带来不便，我会跟进到问题解决。')">安抚致歉</a></div></aside></div><p v-if="notice" class="customer-service-notice" role="alert">{{ notice }}</p></section>
      <section v-else class="customer-service-result"><div class="customer-service-result-heading"><p class="customer-service-kicker">挑战完成</p><h1>{{ result.totalScore }}<small>/100</small></h1><p>{{ result.summary }}</p></div><div class="customer-service-result-grid"><article v-for="item in result.dimensions" :key="item.key"><span>{{ item.label }}</span><strong>{{ item.score }}</strong><p>{{ item.comment }}</p></article></div><section class="customer-service-card customer-service-review"><header><strong>本次表现</strong><span>{{ result.replyCount }} 次回复 · 平均回复 {{ formatLatency(result.averageReplyMs) }}</span></header><ul><li v-for="item in result.improvements" :key="item">{{ item }}</li></ul></section><div class="customer-service-result-actions"><button class="customer-service-secondary" type="button" @click="resetView"><RefreshCw :size="16"/>再练一次</button><button class="customer-service-primary" type="button" @click="emit('back')"><ArrowLeft :size="16"/>返回游戏大厅</button></div></section>
    </main>
  </section>
</template>

<style scoped>
